import manifest from './albums.json'

/**
 * Photo albums from the client (MyAirBridge "Dima Foto Strona", 2026-10-16).
 * Files: public/foto/<album>/NN.webp (1800 px) + NN-t.webp (480 px) + cover.webp (4:3) + cover-p.webp (7:10).
 * albums.json = [name, width, height] per photo, generated by PROJEKTY/Star-Media/Foto_od_klienta/make_albums.py.
 */
export const ALBUMS = manifest as unknown as Record<string, [string, number, number][]>

export const albumPhoto = (album: string, name: string, thumb = false) => `/foto/${album}/${name}${thumb ? '-t' : ''}.webp`
export const albumCover = (album: string) => ({ image: `/foto/${album}/cover.webp`, poster: `/foto/${album}/cover-p.webp`, album })
